-- Oracle Database 12c Enterprise Edition Release 12.1.0.2.0 - 64bit Production

CREATE TABLE HARVEST.GROWERS (
  GROWER_ID      NUMBER(10) NOT NULL,
  GROWER_NAME    VARCHAR2(100 CHAR) NOT NULL,
  EMAIL          VARCHAR2(200),
  PHONE          VARCHAR2(40),
  BANK_IBAN      VARCHAR2(34),
  DATE_OF_BIRTH  DATE,
  CONSTRAINT PK_GROWERS PRIMARY KEY (GROWER_ID)
);

CREATE TABLE HARVEST.FIELDS (
  FIELD_ID    NUMBER(10) PRIMARY KEY,
  GROWER_ID   NUMBER(10) NOT NULL REFERENCES HARVEST.GROWERS (GROWER_ID),
  HECTARES    NUMBER(8,2) CHECK (HECTARES > 0),
  CROP        VARCHAR2(30)
);

CREATE TABLE HARVEST.DELIVERIES (
  DELIVERY_ID   NUMBER(12) NOT NULL,
  GROWER_ID     NUMBER(10) NOT NULL,
  FIELD_ID      NUMBER(10),
  DELIVERED_ON  DATE NOT NULL,
  WEIGHT_KG     NUMBER(10,1),
  MOISTURE_PCT  NUMBER(4,1),
  STATUS        VARCHAR2(10) DEFAULT 'NEW' NOT NULL,
  NOTES         LONG,
  CONSTRAINT PK_DELIVERIES PRIMARY KEY (DELIVERY_ID),
  CONSTRAINT FK_DEL_GROWER FOREIGN KEY (GROWER_ID) REFERENCES HARVEST.GROWERS (GROWER_ID),
  CONSTRAINT CK_DEL_STATUS CHECK (STATUS IN ('NEW','TESTED','PAID','REJECTED'))
);
CREATE INDEX HARVEST.IX_DEL_GROWER ON HARVEST.DELIVERIES (GROWER_ID);
ALTER TABLE HARVEST.DELIVERIES ADD CONSTRAINT FK_DEL_FIELD FOREIGN KEY (FIELD_ID) REFERENCES HARVEST.FIELDS (FIELD_ID);

CREATE TABLE HARVEST.QUALITY_TESTS (
  TEST_ID      NUMBER(12) PRIMARY KEY,
  DELIVERY_ID  NUMBER(12) NOT NULL,
  GRADE        CHAR(1),
  TESTED_AT    TIMESTAMP WITH TIME ZONE,
  CONSTRAINT FK_QT_DELIVERY FOREIGN KEY (DELIVERY_ID) REFERENCES HARVEST.DELIVERIES (DELIVERY_ID)
);

CREATE TABLE SETTLE.PRICE_RULES (
  RULE_ID     NUMBER(6) PRIMARY KEY,
  CROP        VARCHAR2(30) NOT NULL,
  GRADE       CHAR(1) NOT NULL,
  PRICE_PER_T NUMBER(10,2) NOT NULL
);

CREATE TABLE SETTLE.PAYMENTS (
  PAYMENT_ID   NUMBER(12) PRIMARY KEY,
  DELIVERY_ID  NUMBER(12) NOT NULL,
  AMOUNT       NUMBER(12,2) NOT NULL,
  PAID_ON      DATE,
  CONSTRAINT FK_PAY_DELIVERY FOREIGN KEY (DELIVERY_ID) REFERENCES HARVEST.DELIVERIES (DELIVERY_ID)
);
CREATE INDEX SETTLE.IX_PAY_DEL ON SETTLE.PAYMENTS (DELIVERY_ID);

CREATE TABLE SETTLE.AUDIT_LOG (
  LOGGED_AT  TIMESTAMP,
  ACTION     VARCHAR2(50),
  DETAIL     VARCHAR2(4000)
);

CREATE TABLE SETTLE.APP_USERS (
  USER_ID    NUMBER(6) PRIMARY KEY,
  LOGIN      VARCHAR2(30) NOT NULL,
  PASSWORD   VARCHAR2(30) NOT NULL
);

CREATE TABLE HARVEST.OLD_IMPORT (
  IMPORT_ROW  NUMBER,
  ATTRIBUTE1  VARCHAR2(150),
  ATTRIBUTE2  VARCHAR2(150),
  ATTRIBUTE3  VARCHAR2(150),
  ATTRIBUTE4  VARCHAR2(150),
  ATTRIBUTE5  VARCHAR2(150),
  ATTRIBUTE6  VARCHAR2(150)
);

CREATE SEQUENCE SETTLE.PAYMENT_SEQ START WITH 1;
